import { DomainError } from "../domain/DomainError";
import { OrderRepository } from "../domain/OrderRepository";
import { StockService } from "../domain/StockService";
import { OrderDto, toOrderDto } from "./OrderDto";

export class CancelOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly stock: StockService,
  ) {}

  execute(orderId: string): OrderDto {
    const order = this.orders.findById(orderId);
    if (!order) {
      throw new DomainError("not_found", `Order ${orderId} does not exist`);
    }
    order.cancel();
    this.stock.release(order.lines);
    this.orders.save(order);
    return toOrderDto(order);
  }
}

