import { DomainError } from "../domain/DomainError";
import { OrderRepository } from "../domain/OrderRepository";
import { isOrderState } from "../domain/OrderState";
import { OrderDto, toOrderDto } from "./OrderDto";

export class ListOrdersByStateUseCase {
  constructor(private readonly orders: OrderRepository) {}

  execute(state?: string): OrderDto[] {
    if (state === undefined) {
      return this.orders.findAll().map(toOrderDto);
    }
    if (!isOrderState(state)) {
      throw new DomainError("invalid", `Unknown order state: ${state}`);
    }
    return this.orders.findByState(state).map(toOrderDto);
  }
}

